func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/factories/{factory_id}/draft", wrapper.GetDraft)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/factories/{factory_id}/draft", wrapper.PutDraft)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/factories/{factory_id}/publish", wrapper.PublishFactory)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/runs/{run_id}", wrapper.GetRun)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/runs/{run_id}/trace", wrapper.GetRunTrace)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/configs/{config_id}", wrapper.GetConfig)

	return m
}

